 \sin\left(\frac{\beta}{2}\right)
 &= \frac{1}{\sqrt{2}}\sin\left(\frac{\alpha}{2}\right)\\
 \equiv && \sqrt{2} &= \frac{\sin\left(\frac{\alpha}{2}\right)}{\sin\left(\frac{\beta}{2}\right)}\tag{4}
\end{align}

